/**
 * `@stream-io/i18n` — the translation runtime shared across Stream's JS SDKs.
 *
 * Framework-agnostic: React bindings are behind `./react`, the Node-only catalog generator
 * behind `./codegen`. Keep this free of module-scope side effects — every `Dayjs.extend` goes
 * through `ensureDayjsPlugins()`, which is what makes `sideEffects: false` honest.
 */
export * from "./dayjs.ts";
export * from "./formatters.ts";
export * from "./Streami18n.ts";
export * from "./TranslationBuilder.ts";
export * from "./TranslationStore.ts";
export * from "./translator.ts";
export * from "./types.ts";
